--
-- Table structure for table `extreme_goals_odds_record`
--

DROP TABLE IF EXISTS `extreme_goals_odds_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `extreme_goals_odds_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `match_date` date NOT NULL COMMENT '比赛日期 (YYYY-MM-DD)',
  `batch_title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次/赛事组 (如 日职周六精选, 荷甲第10轮)',
  `league_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联赛名称 (如 日职联, 韩职K联, 澳超, 巴甲, 葡超, 挪超, 荷甲, 英超, 西甲, 意甲, 德甲, 法甲, 欧冠等)',
  `match_system` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LEAGUE' COMMENT '赛制类型 (LEAGUE:联赛积分制, CUP:杯赛淘汰赛, FRIENDLY:友谊赛, OTHER:其他)',
  `home_team` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主队名称',
  `away_team` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客队名称',
  `zero_goals_odds` decimal(6,2) NOT NULL COMMENT '0球打出初盘/终盘赔率 (如 9.50, 11.00)',
  `seven_goals_odds` decimal(6,2) NOT NULL COMMENT '7球+打出初盘/终盘赔率 (如 26.00, 35.00)',
  `odds_ratio` decimal(6,2) DEFAULT NULL COMMENT '两极赔率比率 (7+赔率 / 0球赔率)',
  `total_goals` int NOT NULL COMMENT '全场实际开奖总进球数 (0, 1, 2, 3, 4, 5, 6, 7+)',
  `full_score` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '全场比分 (如 2:1)',
  `goals_category` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进球数分类 (ZERO_ONE:0-1小球, TWO_THREE:2-3中球, FOUR_SIX:4-6大球, SEVEN_PLUS:7+超大球)',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复盘心得与备忘',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_egor_match_date` (`match_date`),
  KEY `idx_egor_league_name` (`league_name`),
  KEY `idx_egor_match_system` (`match_system`),
  KEY `idx_egor_zero_odds` (`zero_goals_odds`),
  KEY `idx_egor_seven_odds` (`seven_goals_odds`),
  KEY `idx_egor_total_goals` (`total_goals`),
  KEY `idx_egor_goals_category` (`goals_category`)
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='0球与7球两极进球赔率大数据统计表';
/*!40101 SET character_set_client = @saved_cs_client */;

