--
-- Table structure for table `football_match`
--

DROP TABLE IF EXISTS `football_match`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `football_match` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '比赛主键ID',
  `match_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '比赛外部/业务唯一编号',
  `league_id` bigint NOT NULL COMMENT '关联联赛ID',
  `league_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联赛编码',
  `league_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联赛名称快照',
  `season_id` bigint NOT NULL COMMENT '关联赛季ID',
  `season_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛季名称快照 (如 2024-2025)',
  `round_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '轮次/阶段 (如 第28轮, 小组赛A组第1轮, 1/8决赛)',
  `home_team` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主队名称',
  `away_team` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客队名称',
  `match_time` datetime NOT NULL COMMENT '比赛开球时间 (北京时间)',
  `venue` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '比赛球场',
  `home_score` int DEFAULT NULL COMMENT '完场主队得分',
  `away_score` int DEFAULT NULL COMMENT '完场客队得分',
  `half_home_score` int DEFAULT NULL COMMENT '半场主队得分',
  `half_away_score` int DEFAULT NULL COMMENT '半场客队得分',
  `result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '赛果 (HOME_WIN:主胜, DRAW:平局, AWAY_WIN:客胜)',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SCHEDULED' COMMENT '比赛状态 (SCHEDULED:未开赛, IN_PROGRESS:进行中, FINISHED:已完赛, POSTPONED:延期, CANCELLED:取消)',
  `is_settled` int NOT NULL,
  `settled_at` datetime DEFAULT NULL COMMENT '结算时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_match_code` (`match_code`),
  KEY `idx_match_league_season` (`league_code`,`season_name`),
  KEY `idx_match_time` (`match_time`),
  KEY `idx_match_status` (`status`),
  KEY `idx_match_settled` (`is_settled`),
  KEY `idx_match_teams` (`home_team`,`away_team`,`match_time`),
  KEY `fk_match_league` (`league_id`),
  KEY `fk_match_season` (`season_id`),
  CONSTRAINT `fk_match_league` FOREIGN KEY (`league_id`) REFERENCES `league` (`id`),
  CONSTRAINT `fk_match_season` FOREIGN KEY (`season_id`) REFERENCES `season` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=91 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='足球比赛表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `football_match`
--

