--
-- Table structure for table `handicap_match_record`
--

DROP TABLE IF EXISTS `handicap_match_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `handicap_match_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '比赛明细主键ID',
  `match_date` date NOT NULL COMMENT '比赛日期 (YYYY-MM-DD)',
  `batch_title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次/赛事组 (如 英超第10轮, 周末精选)',
  `league_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联赛名称 (如 英超, 西甲, 意甲, 德甲, 欧冠)',
  `match_system` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LEAGUE' COMMENT '赛制类型 (LEAGUE:联赛积分制, CUP:杯赛淘汰赛, FRIENDLY:友谊赛, OTHER:其他)',
  `home_team` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主队名称',
  `away_team` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客队名称',
  `handicap_side` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HOME' COMMENT '让球方 (HOME:主让, AWAY:客让)',
  `handicap_value` decimal(4,2) NOT NULL DEFAULT '-1.00' COMMENT '让球盘口数值 (-1.00:让1球, -0.75:半一, -1.25:一球球半)',
  `home_win_odds` decimal(6,2) NOT NULL COMMENT '主胜初盘/终盘赔率',
  `draw_odds` decimal(6,2) DEFAULT NULL COMMENT '平局赔率',
  `away_win_odds` decimal(6,2) NOT NULL COMMENT '客胜初盘/终盘赔率',
  `handicap_odds` decimal(6,2) NOT NULL COMMENT '让球方获胜赔率 (动态步幅分桶核心依据)',
  `half_score` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '半场比分 (如 1:0)',
  `full_score` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '全场比分 (如 2:0)',
  `match_result` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '最终开奖赛果 (HOME_WIN:主胜, DRAW:平局, AWAY_WIN:客胜)',
  `result_odds` decimal(6,2) NOT NULL COMMENT '赛果对应的打出赔率',
  `handicap_result` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '让球盘开奖结果 (WIN:让胜, DRAW:让平/走水, LOSS:让负)',
  `handicap_result_odds` decimal(6,2) DEFAULT NULL COMMENT '让球盘开奖打出赔率',
  `half_full_result` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '半全场赛果 (如 胜胜, 平胜, 胜平, 平平, 负负)',
  `total_goals` int DEFAULT NULL COMMENT '全场总进球数',
  `is_break` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否打穿盘口 (1:穿盘, 0:未穿盘/卡盘/翻车)',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复盘心得与备忘',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_hmr_match_date` (`match_date`),
  KEY `idx_hmr_handicap_side` (`handicap_side`),
  KEY `idx_hmr_handicap_odds` (`handicap_odds`),
  KEY `idx_hmr_is_break` (`is_break`),
  KEY `idx_hmr_match_result` (`match_result`),
  KEY `idx_hmr_match_system` (`match_system`),
  KEY `idx_hmr_batch_title` (`batch_title`)
) ENGINE=InnoDB AUTO_INCREMENT=524 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='单场比赛精细化让球与开奖明细记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `handicap_match_record`
--

LOCK TABLES `handicap_match_record` WRITE;
