  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联赛唯一编码 (如 PL, LA_LIGA, SERIE_A, BUNDESLIGA, LIGUE_1, UCL, WORLD_CUP, EURO)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联赛完整名称 (如 英格兰足球超级联赛)',
  `short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联赛简称 (如 英超, 西甲, 意甲, 德甲, 法甲, 欧冠, 世界杯, 欧洲杯)',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛事分类 (BIG_FIVE_LEAGUE:五大联赛, CONTINENTAL_CUP:洲际杯赛, INTERNATIONAL_CUP:国际大赛, OTHER:其他)',
  `country` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属国家/地区 (如 英格兰, 西班牙, 欧洲, 全球)',
  `logo_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联赛Logo图URL',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重 (数字越小越靠前)',
  `status` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_league_code` (`code`),
  KEY `idx_league_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='联赛与杯赛字典表';
/*!40101 SET character_set_client = @saved_cs_client */;

