INSERT INTO `league` VALUES (1,'PL','英格兰足球超级联赛','英超','BIG_FIVE_LEAGUE','英格兰',NULL,1,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(2,'LA_LIGA','西班牙足球甲级联赛','西甲','BIG_FIVE_LEAGUE','西班牙',NULL,2,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(3,'SERIE_A','意大利足球甲级联赛','意甲','BIG_FIVE_LEAGUE','意大利',NULL,3,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(4,'BUNDESLIGA','德国足球甲级联赛','德甲','BIG_FIVE_LEAGUE','德国',NULL,4,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(5,'LIGUE_1','法国足球甲级联赛','法甲','BIG_FIVE_LEAGUE','法国',NULL,5,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(6,'UCL','欧洲冠军联赛','欧冠','CONTINENTAL_CUP','欧洲',NULL,6,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(7,'WORLD_CUP','国际足联世界杯','世界杯','INTERNATIONAL_CUP','全球',NULL,7,1,'2026-09-11 19:58:59','2026-09-11 19:58:59'),(8,'EURO','欧洲足球锦标赛','欧洲杯','INTERNATIONAL_CUP','欧洲',NULL,8,1,'2026-09-11 19:58:59','2026-09-11 19:58:59');
