--
-- Table structure for table `match_prediction`
--

DROP TABLE IF EXISTS `match_prediction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `match_prediction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预测记录主键ID',
  `match_id` bigint NOT NULL COMMENT '关联足球比赛ID',
  `ai_model_id` bigint NOT NULL COMMENT '关联AI模型ID',
  `ai_model_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AI模型编码 (如 GPT, QWEN)',
  `predicted_result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预测胜负赛果 (HOME_WIN:主胜, DRAW:平局, AWAY_WIN:客胜)',
  `result_odds` decimal(6,2) DEFAULT '1.85' COMMENT '胜负预测对应赔率',
  `predicted_results_json` text COLLATE utf8mb4_unicode_ci,
  `predicted_scores_json` text COLLATE utf8mb4_unicode_ci,
  `predicted_goals_json` text COLLATE utf8mb4_unicode_ci,
  `predicted_scores` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '兼容最多3个预测比分字符串',
  `predicted_goals` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '兼容最多3个预测总进球数字符串',
  `predicted_home_score` int DEFAULT NULL COMMENT '兼容单个预测主队得分',
  `predicted_away_score` int DEFAULT NULL COMMENT '兼容单个预测客队得分',
  `confidence` decimal(5,2) DEFAULT NULL COMMENT 'AI预测置信度 (0.00 ~ 100.00%)',
  `analysis_summary` text COLLATE utf8mb4_unicode_ci,
  `detailed_analysis` mediumtext COLLATE utf8mb4_unicode_ci,
  `predicted_odds` decimal(6,2) DEFAULT NULL COMMENT '全局参考赔率',
  `settle_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '结算状态 (PENDING:未结算, WON:红单/命中, LOST:黑单/未命中, VOID:走水/无效)',
  `is_result_correct` int DEFAULT NULL COMMENT '胜负方向是否命中 (1:命中, 0:未命中)',
  `is_score_correct` int DEFAULT NULL COMMENT '比分是否命中(3个比分命中其一即为1) (1:命中, 0:未命中)',
  `hit_score` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '命中的具体比分 (如 2-1)',
  `is_goals_correct` int DEFAULT NULL COMMENT '进球数是否命中(3个进球数命中其一即为1) (1:命中, 0:未命中)',
  `hit_goals` int DEFAULT NULL COMMENT '命中的具体进球数 (如 3)',
  `hit_importance` int NOT NULL DEFAULT '0' COMMENT '命中重要性等级 (1:比分最高, 2:进球数次之, 3:胜负基础, 0:未命中)',
  `hit_tier` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '命中级别标识 (PERFECT_HIT, SCORE_HIT, GOALS_HIT, RESULT_HIT, MISSED)',
  `hit_tier_desc` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '命中级别描述 (如 ?精准比分, ⚽进球数命中, ?全中大满贯)',
  `options_count` int NOT NULL DEFAULT '7' COMMENT '本场预测选项总数 (初始利润负数源, 如 胜负2+比分3+进球3=8项)',
  `initial_profit` decimal(8,2) NOT NULL DEFAULT '-7.00' COMMENT '初始利润 (如 -8.00)',
  `stake_amount` decimal(8,2) NOT NULL DEFAULT '7.00' COMMENT '本场投入总注数 (如 7.00 或 8.00)',
  `return_amount` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '本场中奖总返还金额',
  `net_profit` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '本场净赚倍数 (return_amount - stake_amount)',
  `result_return` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '胜负玩法中奖返还',
  `score_return` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '比分玩法中奖返还',
  `goals_return` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '进球数玩法中奖返还',
  `settled_at` datetime DEFAULT NULL COMMENT '结算时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_match_ai_model` (`match_id`,`ai_model_code`),
  KEY `idx_pred_model_settle` (`ai_model_code`,`settle_status`),
  KEY `idx_pred_match` (`match_id`),
  KEY `fk_pred_ai_model` (`ai_model_id`),
  CONSTRAINT `fk_pred_ai_model` FOREIGN KEY (`ai_model_id`) REFERENCES `ai_model` (`id`),
  CONSTRAINT `fk_pred_match` FOREIGN KEY (`match_id`) REFERENCES `football_match` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI比赛预测明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `match_prediction`
--

LOCK TABLES `match_prediction` WRITE;
/*!40000 ALTER TABLE `match_prediction` DISABLE KEYS */;
INSERT INTO `match_prediction` VALUES (1,1,1,'GPT','HOME_WIN',1.13,'[{\"result\":\"HOME_WIN\",\"odds\":1.13}]','[{\"score\":\"2-0\",\"odds\":5.7},{\"score\":\"2-1\",\"odds\":8.25},{\"score\":\"1-0\",\"odds\":6.7}]','[{\"goals\":2,\"odds\":3.9},{\"goals\":3,\"odds\":3.7}]','2-0,2-1,1-0','2,3',NULL,NULL,52.50,'特别需要注意的是，科莫刚经历欧冠4-1大胜，市场热度可能明显偏向主队。所以如果临场科莫让步已经升到 -1.5甚至-1.75，我反而会降低对穿盘的信心，更倾向科莫赢球、帕尔马受让。',NULL,NULL,'WON',1,1,'2-1',1,3,1,'PERFECT_HIT','🌟 全中大满贯',6,-6.00,6.00,13.08,7.08,1.13,8.25,3.70,'2026-09-15 08:33:17','2026-09-14 13:53:31','2026-09-15 08:33:17'),(2,1,2,'QWEN','HOME_WIN',1.13,'[{\"result\":\"HOME_WIN\",\"odds\":1.13}]','[{\"score\":\"2-0\",\"odds\":5.7},{\"score\":\"2-1\",\"odds\":8.25},{\"score\":\"1-0\",\"odds\":6.7}]','[{\"goals\":2,\"odds\":3.9},{\"goals\":3,\"odds\":3.7}]','2-0,2-1,1-0','2,3',NULL,NULL,58.00,'从战术和数据模型来看，科莫在主场势必会掌控比赛节奏，而帕尔马受限于进攻乏力，大概率只能采取低位防守和长传反击的策略。尽管科莫进攻端优势巨大，但考虑到欧冠后的体能消耗以及自身防线尚未完全稳固，比赛走势可能会比外界预期的更加谨慎，主队未必能轻松打出超大比分',NULL,NULL,'WON',1,1,'2-1',1,3,1,'PERFECT_HIT','🌟 全中大满贯',6,-6.00,6.00,13.08,7.08,1.13,8.25,3.70,'2026-09-15 08:33:17','2026-09-14 13:53:31','2026-09-15 08:33:17'),(3,2,1,'GPT','AWAY_WIN',1.42,'[{\"result\":\"AWAY_WIN\",\"odds\":1.42}]','[{\"score\":\"0-2\",\"odds\":7.5},{\"score\":\"0-1\",\"odds\":7.25},{\"score\":\"1-2\",\"odds\":7}]','[{\"goals\":2,\"odds\":3.7},{\"goals\":3,\"odds\":3.7}]','0-2,0-1,1-2','2,3',NULL,NULL,72.50,'不过有一个需要注意的因素：罗马刚经历欧战，而且接下来赛程比较密集，本场又是客场，因此我不太看好罗马轻松大胜。罗马赢球，但大概率不是大比分。',NULL,NULL,'WON',1,1,'0-2',1,2,1,'PERFECT_HIT','🌟 全中大满贯',6,-6.00,6.00,12.62,6.62,1.42,7.50,3.70,'2026-09-15 08:32:44','2026-09-14 14:03:07','2026-09-15 08:32:44'),(4,2,2,'QWEN','AWAY_WIN',1.42,'[{\"result\":\"AWAY_WIN\",\"odds\":1.42}]','[{\"score\":\"0-1\",\"odds\":7.25},{\"score\":\"1-1\",\"odds\":7.5},{\"score\":\"1-2\",\"odds\":7}]','[{\"goals\":1,\"odds\":5.2},{\"goals\":2,\"odds\":3.7},{\"goals\":3,\"odds\":3.7}]','0-1,1-1,1-2','1,2,3',NULL,NULL,78.00,'从战术层面来看，罗马在实力和状态上全面占优，但考虑到周中欧冠的体能消耗以及迪巴拉、科内等核心可能轮休，罗马的进攻创造力将打折扣。都灵虽然防线残缺，但主场作战势必会摆出低位防守反击的姿态，拼抢意愿强烈。因此，罗马在客场大概率会采取稳扎稳打的策略，以控制比赛和小胜为主，比赛陷入胶着对峙的可能性较高。',NULL,NULL,'WON',1,0,NULL,1,2,2,'GOALS_RESULT_HIT','⚽ 进球数+胜负命中',7,-7.00,7.00,5.12,-1.88,1.42,0.00,3.70,'2026-09-15 08:32:44','2026-09-14 14:03:07','2026-09-15 08:32:44'),(5,3,1,'GPT','HOME_WIN',1.14,'[{\"result\":\"HOME_WIN\",\"odds\":1.14}]','[{\"score\":\"2-1\",\"odds\":8},{\"score\":\"3-1\",\"odds\":9.5},{\"score\":\"2-0\",\"odds\":6.5}]','[{\"goals\":2,\"odds\":4.25},{\"goals\":3,\"odds\":3.7},{\"goals\":4,\"odds\":4.5}]','2-1,3-1,2-0','2,3,4',NULL,NULL,62.50,'国米最大的优势还是主场进攻火力。近期主场5场打进13球，本赛季联赛主场又连续击败蒙扎、那不勒斯，进攻端状态不错。\n乌迪内斯的问题在于本场伤停相对比较多，包括扎尼奥洛、彼得罗夫斯基以及部分后防球员，这会影响他们的防守反击质量。\n不过国米刚刚经历欧冠客场对皇马的比赛，且左路迪马尔科缺阵，所以我不太看好国米轻松打穿。',NULL,NULL,'WON',1,0,NULL,0,NULL,3,'RESULT_HIT','🚩 胜负命中',7,-7.00,7.00,1.14,-5.86,1.14,0.00,0.00,'2026-09-15 08:28:29','2026-09-14 14:22:45','2026-09-15 08:28:29'),(6,3,2,'QWEN','HOME_WIN',1.14,'[{\"result\":\"HOME_WIN\",\"odds\":1.14}]','[{\"score\":\"3-1\",\"odds\":9.5},{\"score\":\"2-0\",\"odds\":6.5},{\"score\":\"2-1\",\"odds\":8}]','[{\"goals\":2,\"odds\":4.25},{\"goals\":3,\"odds\":3.7},{\"goals\":4,\"odds\":4.5}]','3-1,2-0,2-1','2,3,4',NULL,NULL,58.00,'从战术和数据模型来看，国米在主场实力与进攻火力上全面占优，但欧冠后的体能瓶颈和边路伤病是最大隐患。乌迪内斯虽然残阵出击，但其务实的防守反击战术和过往在梅阿查爆冷的经验，足以让他们在国米防线疲惫时制造威胁。综合泊松分布模型与各方前瞻，本场比赛国米大概率能顺利拿下三分，但很难做到绝对零封，双方均有进球的可能性较高。',NULL,NULL,'WON',1,0,NULL,0,NULL,3,'RESULT_HIT','🚩 胜负命中',7,-7.00,7.00,1.14,-5.86,1.14,0.00,0.00,'2026-09-15 08:28:29','2026-09-14 14:22:45','2026-09-15 08:28:29'),(7,4,1,'GPT','AWAY_WIN',2.77,'[{\"result\":\"AWAY_WIN\",\"odds\":2.77},{\"result\":\"DRAW\",\"odds\":3.25}]','[{\"score\":\"1-2\",\"odds\":9},{\"score\":\"2-2\",\"odds\":11.5},{\"score\":\"1-1\",\"odds\":6.75}]','[{\"goals\":2,\"odds\":3.75},{\"goals\":3,\"odds\":3.65},{\"goals\":4,\"odds\":5.1}]','1-2,2-2,1-1','2,3,4',NULL,NULL,32.50,'我预计这场不会像传统意义上的英超强弱分明比赛。\n比较可能的走势：\n上半场：\n双方比较谨慎，利兹利用主场气势主动压迫，纽卡寻找反击。\n下半场：\n随着比赛空间扩大，双方都有进球机会。纽卡的攻击能力让我比较看好他们至少进1球，而利兹主场也有较大概率取得进球。',NULL,NULL,'LOST',0,0,NULL,0,NULL,0,'MISSED','⚫ 未命中',8,-8.00,8.00,0.00,-8.00,0.00,0.00,0.00,'2026-09-15 08:27:48','2026-09-14 14:42:20','2026-09-15 08:27:48'),(8,4,2,'QWEN','HOME_WIN',2.15,'[{\"result\":\"HOME_WIN\",\"odds\":2.15},{\"result\":\"DRAW\",\"odds\":3.25}]','[{\"score\":\"2-1\",\"odds\":7.5},{\"score\":\"2-2\",\"odds\":11.5},{\"score\":\"1-2\",\"odds\":9}]','[{\"goals\":3,\"odds\":3.75},{\"goals\":4,\"odds\":5.1}]','2-1,2-2,1-2','3,4',NULL,NULL,78.00,'从战术和数据模型来看，这是一场势均力敌的中游卡位战。利兹联坐拥魔鬼主场，且纽卡斯尔联后防线多名主力伤缺，利兹联的高位逼抢有望在开局阶段制造杀机。但纽卡斯尔联的进攻端目前处于“超额发挥”状态，锋线核心得分能力极强，面对利兹联残缺的防线，喜鹊军团完全有能力取得进球。\n综合泊松分布模型与各方前瞻，本场比赛双方都有很大机会破门，打出大比分的概率较高。',NULL,NULL,'WON',1,0,NULL,0,NULL,3,'RESULT_HIT','🚩 胜负命中',7,-7.00,7.00,2.15,-4.85,2.15,0.00,0.00,'2026-09-15 08:27:48','2026-09-14 14:42:20','2026-09-15 08:27:48'),(9,5,1,'GPT','HOME_WIN',1.86,'[{\"result\":\"HOME_WIN\",\"odds\":1.86}]','[{\"score\":\"2-1\",\"odds\":7.5},{\"score\":\"2-2\",\"odds\":11},{\"score\":\"1-2\",\"odds\":11.5}]','[{\"goals\":2,\"odds\":4.1},{\"goals\":3,\"odds\":3.5},{\"goals\":4,\"odds\":4.54}]','2-1,2-2,1-2','2,3,4',NULL,NULL,72.50,'目前两队走势存在明显反差：比利亚雷亚尔联赛前4轮还没有赢球，而且近期防守端连续出现问题；贝蒂斯则拿到3胜1负，并且刚刚击败皇马、欧冠又战胜里尔，状态明显更好。\n不过，比利亚雷亚尔坐镇主场，而且双方历史交锋非常容易出现进球：近几次交手中，2-2、2-0、2-1、1-2、3-2等比分比较常见。\n① 比利亚雷亚尔：状态差，但主场不能低估\n比利亚雷亚尔目前最大问题是防守。\n前4轮联赛只拿到2分，并且已经丢了7球；欧冠又被多特蒙德打进3球。球队换帅之后仍处于磨合阶段。\n但他们的问题并不是进攻完全没有威胁。\n主场面对贝蒂斯，依靠佩佩、里克尔梅等球员的个人能力，取得进球的概率依然比较高。',NULL,NULL,'LOST',0,1,'1-2',1,3,1,'SCORE_GOALS_HIT','🎯 比分+进球双中',7,-7.00,7.00,15.00,8.00,0.00,11.50,3.50,'2026-09-15 08:27:09','2026-09-14 14:50:50','2026-09-15 08:27:09'),(10,5,2,'QWEN','AWAY_WIN',3.17,'[{\"result\":\"AWAY_WIN\",\"odds\":3.17},{\"result\":\"DRAW\",\"odds\":3.62}]','[{\"score\":\"1-1\",\"odds\":7.5},{\"score\":\"2-2\",\"odds\":11},{\"score\":\"1-2\",\"odds\":11.5}]','[{\"goals\":2,\"odds\":4.1},{\"goals\":3,\"odds\":3.5}]','1-1,2-2,1-2','2,3',NULL,NULL,78.00,'从战术和数据模型来看，这是一场典型的“保级队死磕欧战劲旅”的对决。比利亚雷亚尔保级战意拉满，主场势必会压上进攻，但这恰好给了状态火热、反击犀利的贝蒂斯身后空当。考虑到比利亚雷亚尔脆弱的临时防线以及双方历史交锋的高进球率（过去5次交锋全部打出至少3球），本场比赛双方均有进球的概率极高。',NULL,NULL,'WON'