  `upset_tendency` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'BALANCED' COMMENT '冷门主客场倾向 (HOME_BIAS:主冷偏多, AWAY_BIAS:客冷偏多, BALANCED:均衡)',
  `risk_level` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'SAFE_NORMAL' COMMENT '综合冷门风险评级 (HIGH_RISK:高危频发, MODERATE:中度震荡, SAFE_NORMAL:正路稳健)',
