--
-- Table structure for table `season`
--

DROP TABLE IF EXISTS `season`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `season` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '赛季主键ID',
  `league_id` bigint NOT NULL COMMENT '关联联赛ID',
  `league_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联联赛编码',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛季名称 (如 2024-2025, 2025-2026, 2026)',
  `start_date` date DEFAULT NULL COMMENT '赛季开始日期',
  `end_date` date DEFAULT NULL COMMENT '赛季结束日期',
  `is_current` int NOT NULL,
  `status` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_league_season` (`league_id`,`name`),
  KEY `idx_season_league_code` (`league_code`),
  KEY `idx_season_name` (`name`),
  CONSTRAINT `fk_season_league` FOREIGN KEY (`league_id`) REFERENCES `league` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='赛事赛季表';
/*!40101 SET character_set_client = @saved_cs_client */;

